    interface Work<T>{T get()throws Exception;} interface Done<T>{void accept(T value);}
    private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);immersive();getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);progressReadOnly=(getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)!=0&&getIntent().getBooleanExtra("progress_test_readonly",false);account=new RemotePluginClient(this);plugin=account;bootstrapPlugin();}
    private void bootstrapPlugin(){page("连接番茄插件","connecting");try{startActivityForResult(account.bootstrapIntent(),4);}catch(Exception e){note(safeError(e));action("重新连接",()->bootstrapPlugin());action("本地书库",()->localLibrary());}}
    private void connectPlugin(){page("连接番茄插件","connecting");load("正在连接数据源…",()->{account.refresh();List<ReadingProgress> legacy=account.legacyProgress();ProgressStore storage=new ProgressStore(this,account.accountScope());for(ReadingProgress p:legacy){ReadingProgress local=storage.get(p.bookId);if(local==null||local.timestamp<p.timestamp)storage.put(p);}return true;},ready->{try{resetProgressSync();home();}catch(Exception e){fatal("账号进度无法打开");}});}
    private void resetProgressSync()throws Exception {
        syncHandler.removeCallbacks(syncRunnable);syncBusy=false;syncAgain=false;resumeProgress=null;syncStatus="尚未同步";
        final String scope=account.accountScope();progressSync=new ProgressSync(new ProgressSync.Client(){private void guard()throws Exception{if(!scope.equals(account.accountScope()))throw new Exception("登录账号已变更");}public ReadingProgress read(String book)throws Exception{guard();return account.readProgress(book);}public void upload(ReadingProgress p)throws Exception{guard();account.uploadProgress(p);}},new ProgressStore(this,scope));
    }
    private boolean canSync(){return plugin==account&&account!=null&&account.loggedIn()&&progressSync!=null;}
    private void status(String value){syncStatus=value;if(syncLabel!=null)syncLabel.setText(value);}
    private void scheduleProgressSync(){if(!canSync())return;syncHandler.removeCallbacks(syncRunnable);syncHandler.postDelayed(syncRunnable,2000);}
    void flushSavedProgress(){
        if(!canSync()||progressReadOnly||worker.isShutdown())return;if(syncBusy){syncAgain=true;return;}syncBusy=true;final ProgressSync engine=progressSync;
        worker.execute(()->{String result=null;boolean retry=false;try{int count=0;for(String book:engine.store.pending()){if(count++>=10){retry=true;break;}ProgressSync.Result sent=engine.flush(book);if(sent==ProgressSync.Result.SENT)result="已与番茄同步";if(sent==ProgressSync.Result.REMOTE_NEWER)result="云端有较新进度，可立即同步到此处";if(sent==ProgressSync.Result.DEFERRED)retry=true;}}catch(Exception e){result="同步失败，本地进度待上传";}final String message=result;final boolean more=retry;runOnUiThread(()->{if(alive&&engine==progressSync){syncBusy=false;if(message!=null)status(message);if(syncAgain||more){syncAgain=false;scheduleProgressSync();}}});});
    }
    private void rememberPosition(ChapterContent chapter,int index,int count,int offset){
        if(!canSync()||progressReadOnly)return;try{ReadingProgress previous=progressSync.store.get(chapter.bookId);long timestamp=Math.max(System.currentTimeMillis(),previous==null?0:previous.timestamp+1);ReadingProgress p=ChapterPosition.capture(chapter,index,count,offset,timestamp);if(p.paragraph<0)return;progressSync.store.put(p);resumeProgress=p;status("本地已保存，等待同步");scheduleProgressSync();}catch(Exception e){status("阅读进度保存失败");}
    }
    private void clearLegacyProgress(){android.content.SharedPreferences.Editor edit=getPreferences(0).edit();for(String key:getPreferences(0).getAll().keySet())if(key.startsWith("chapter.")||key.startsWith("offset."))edit.remove(key);edit.apply();}
    private void immersive(){getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)immersive();}
    @Override public boolean dispatchGenericMotionEvent(MotionEvent event){if(reader==null&&crownScroller.handle(event,scroll))return true;return super.dispatchGenericMotionEvent(event);}
    private void fatal(String message){TextView t=new TextView(this);t.setText(message);t.setTextColor(Color.WHITE);t.setBackgroundColor(0xff0b0f14);t.setPadding(dp(28),dp(40),dp(28),dp(28));setContentView(t);}
    private void page(String title,String name){crownScroller.reset();chapterLoading=false;generation++;screen=name;reader=null;retryAction=null;syncLabel=null;
        root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff0b0f14);root.setPadding(dp(24),dp(16),dp(24),dp(20));
        heading=text(title,15);heading.setSingleLine();heading.setEllipsize(android.text.TextUtils.TruncateAt.END);heading.setGravity(Gravity.CENTER);root.addView(heading,new LinearLayout.LayoutParams(-1,dp(27)));
        nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);root.addView(nav,new LinearLayout.LayoutParams(-1,dp(32)));
        small(nav,"书架",()->home());small(nav,"搜索",()->searchForm());small(nav,"账号",()->accountPage());
        scroll=new ScrollView(this);scroll.setFillViewport(false);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(2),dp(4),dp(2),dp(16));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
    }
    private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xffe6edf5);t.setPadding(dp(4),dp(3),dp(4),dp(3));return t;}
    private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(0xffe6edf5);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff1b293a));b.setMinHeight(dp(38));b.setMinimumHeight(dp(38));b.setPadding(dp(4),dp(3),dp(4),dp(3));b.setOnClickListener(v->action.run());return b;}
    private void small(LinearLayout row,String label,Runnable action){Button b=button(label,action);b.setTextSize(11);b.setMinWidth(0);b.setMinimumWidth(0);row.addView(b,new LinearLayout.LayoutParams(0,-1,1));}
